/**
 * R9 lead: the review package's demo recording (examples/visual-tools/demo-tray.rrd), written once by a committed script
 * (scripts/demo-recording.py, with rerun-sdk 0.38.1) from the demo tray's dimensions and labelled as generated by its own
 * store's application id and the /notes text it holds: the package ships it, the review launcher puts it in tray beside the
 * demo meshes, and Timmy's own header reader (src/vox/recording.ts) reads it as one recording store written by Rerun 0.38.1.
 * What its chunks hold (its entities and time range) is read through the installed Rerun CLI (src/vox/rrd-cli.ts, H159) and
 * tested there; this file checks the committed file itself.
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { readRecording } from '../src/vox/recording.js';

const FILE = 'examples/visual-tools/demo-tray.rrd';

describe('the demo recording (R9 lead)', () => {
  it('ships in the package and is put in tray by the review launcher beside the demo meshes', () => {
    const pkg = JSON.parse(readFileSync('package.json', 'utf8')) as { files: string[] };
    expect(pkg.files).toContain('examples/visual-tools');
    const launcher = readFileSync('scripts/review/review.sh', 'utf8');
    expect(launcher).toContain('cp "$MESHES/demo-tray.rrd" "$TRAY/refs/demo-tray.rrd"');
  });

  it('is a recording Timmy reads: one recording store of the generated tray, written by Rerun 0.38.1, with its footer', () => {
    const b = readFileSync(resolve(FILE));
    expect(b.length).toBeLessThan(64 * 1024);
    const facts = readRecording(b);
    if ('error' in facts) throw new Error(facts.error);
    expect(facts.writer).toBe('Rerun 0.38.1');
    expect(facts.stores).toEqual([{ kind: 'recording', application: 'timmy_demo_generated_tray', recording: 'timmy-demo-tray-1' }]);
    expect(facts.messages.chunks).toBeGreaterThan(0);
    expect(facts.ended).toBe(true);
    expect(facts.footer).toBe(true);
    expect(facts.stopped).toBeUndefined();
  });

  it('says in its own words that it is generated, not a capture, and holds nothing of the computer that wrote it', () => {
    const text = readFileSync(resolve(FILE)).toString('latin1');
    expect(text).toContain('TIMMY DEMO RECORDING: generated by scripts/demo-recording.py');
    for (const never of ['/home/', '/Users/', '/root', '/tmp/', 'claude']) expect(text).not.toContain(never);
  });
});
